#include <stdio.h>
enum Kind { KIND_INTEGER, KIND_REAL };
struct Value { enum Kind kind; union { int integer; double real; } data; };
int main(void) { struct Value v = {.kind=KIND_REAL, .data.real=3.5}; if (v.kind == KIND_REAL) printf("%.1f\n", v.data.real); return 0; }
